import{_ as e,c as t,o as n,a as r}from"./app.c62f2221.js";const p=JSON.parse('{"title":"CS 402: Frontiers in Deep Learning","description":"","frontmatter":{},"headers":[{"level":2,"title":"General Information","slug":"general-information"},{"level":2,"title":"Course Description","slug":"course-description"},{"level":2,"title":"Textbooks","slug":"textbooks"},{"level":2,"title":"Grading","slug":"grading"}],"relativePath":"teaching/dl/index.md"}'),i={name:"teaching/dl/index.md"},o=r('<h1 id="cs-402-frontiers-in-deep-learning" tabindex="-1">CS 402: Frontiers in Deep Learning <a class="header-anchor" href="#cs-402-frontiers-in-deep-learning" aria-hidden="true">#</a></h1><div class="info custom-block"><p class="custom-block-title">Announcements</p><p><strong>Spring 2026</strong>: Welcome! This course covers the latest advancements in Deep Learning. <strong>Prerequisites</strong>: Basic Machine Learning &amp; Python/PyTorch proficiency.</p></div><h2 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-hidden="true">#</a></h2><table><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Instructor</strong></td><td style="text-align:left;"><strong>Yongli Zhu</strong> (<a href="mailto:yongliz@tamu.edu">yongliz@tamu.edu</a>)<br>Office: WEB 320G</td></tr><tr><td style="text-align:left;"><strong>Lectures</strong></td><td style="text-align:left;">Tue/Thu 1:00 PM \u2013 2:30 PM<br>Room: HRBB 124</td></tr><tr><td style="text-align:left;"><strong>Office Hours</strong></td><td style="text-align:left;">Friday 2:00 PM \u2013 4:00 PM</td></tr></tbody></table><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-hidden="true">#</a></h2><p>This course provides a deep dive into modern deep learning techniques. While we start with the foundations, the focus is on state-of-the-art architectures including Transformers, Generative Models (Diffusion, GANs), and Large Language Models (LLMs).</p><p><strong>Topics include:</strong></p><ul><li>Deep Feedforward Networks &amp; Regularization</li><li>Convolutional Networks (CNNs) &amp; Computer Vision</li><li>Sequence Modeling (RNNs, LSTMs, Attention)</li><li><strong>Transformers &amp; LLMs</strong> (BERT, GPT)</li><li>Generative Models (Diffusion Models, VAEs)</li><li>Deep Reinforcement Learning</li></ul><h2 id="textbooks" tabindex="-1">Textbooks <a class="header-anchor" href="#textbooks" aria-hidden="true">#</a></h2><ul><li><strong>Primary Text (The &quot;Flower Book&quot;)</strong>: <ul><li><em>Deep Learning</em> by Ian Goodfellow, Yoshua Bengio, and Aaron Courville. (<a href="https://www.deeplearningbook.org/" target="_blank" rel="noopener noreferrer">Online Version</a>)</li></ul></li><li><strong>References</strong>: <ul><li><em>Dive into Deep Learning</em> (Zhang et al.)</li><li>Recent conference papers (NeurIPS, ICLR, CVPR).</li></ul></li></ul><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-hidden="true">#</a></h2><ul><li><strong>Coding Assignments (40%)</strong>: PyTorch-based implementations.</li><li><strong>Midterm Exam (20%)</strong>: Theory and concepts.</li><li><strong>Final Project (40%)</strong>: Research-oriented project in teams.</li></ul><br><div style="display:flex;justify-content:flex-end;margin-top:2rem;"><a href="./lectures" style="font-size:1.1em;font-weight:bold;color:var(--vp-c-brand);"> Next: Lectures &amp; Schedule \u2192 </a></div>',14),a=[o];function s(l,d,c,g,h,u){return n(),t("div",null,a)}var m=e(i,[["render",s]]);export{p as __pageData,m as default};
